import heapq


def most_capital(w: int, k: int, profits: list[int], capital: list[int]) -> int:
    projects = sorted(zip(capital, profits))     # by the capital each one needs
    ready = []                                   # max-heap (negated) of affordable profits
    i = 0
    for _ in range(k):
        while i < len(projects) and projects[i][0] <= w:
            heapq.heappush(ready, -projects[i][1])   # unlocked: capital never drops again
            i += 1
        if not ready:
            break                                # nothing affordable now or ever
        w -= heapq.heappop(ready)                # the most profitable affordable project
    return w

perf.naive:
def most_capital(w: int, k: int, profits: list[int], capital: list[int]) -> int:
    done = [False] * len(profits)
    for _ in range(k):
        best = -1
        for i in range(len(profits)):            # rescan every project for each pick
            if not done[i] and capital[i] <= w and (best == -1 or profits[i] > profits[best]):
                best = i
        if best == -1:
            break
        done[best] = True
        w += profits[best]
    return w
